  function melt(pz){if(pz.mDirty){pz.mDirty=false;const g=pz.mc.getContext('2d');g.clearRect(0,0,2*PC.r,2*PC.r);for(let j=0;j<N;j++)for(let i=0;i<N;i++){const v=pz.cg[j*N+i];if(v<.25)continue;g.fillStyle=v>1.5?'#f5cf58':'#f8dc80';g.beginPath();g.arc((i+.5)*CS,(j+.5)*CS,CS*(.62+Math.min(v,2)*.2),0,7);g.fill()}}return pz.mc}
  const cov=(a,th)=>inside.reduce((n,i)=>n+(a[i]>=th?1:0),0)/inside.length,avgC=pz=>inside.reduce((s,i)=>s+Math.min(3,pz.cg[i]),0)/inside.length;
