    const ss=(pz.sauceType===o.sauce?1:pz.sauceType?.35:0)*clamp((cov(pz.sg,1)-.25)/.62,0,1)*(1-Math.max(0,ring.reduce((n,i)=>n+pz.sg[i],0)/ring.length-.2)*.9);
