  if(k==='patty'){x.beginPath();x.roundRect(cx-w/2+3,y-17,w-6,20,9);x.fill();x.stroke();x.fillStyle='rgba(0,0,0,.25)';for(let i=0;i<9;i++)x.fillRect(cx-w/2+10+((i*37)%(w-22)),y-13+((i*7)%12),3,2);x.fillStyle='rgba(255,255,255,.12)';x.fillRect(cx-w/2+8,y-15,w-16,3);return 16}
